CREATE TABLE IF NOT EXISTS agentHierarchy(agentEmail TEXT PRIMARY KEY,uplineEmail TEXT,updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS portalWhatsappGrants(email TEXT PRIMARY KEY,enabled INTEGER NOT NULL DEFAULT 0,updatedBy TEXT,updatedAt TEXT DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO agentHierarchy(agentEmail,uplineEmail) SELECT lower(email),NULL FROM adminAccounts WHERE lower(trim(name))='rafael cunha' AND accountType IN ('both','admin') ORDER BY id LIMIT 1;
INSERT OR IGNORE INTO agentHierarchy(agentEmail,uplineEmail) SELECT lower(a.email),(SELECT lower(email) FROM adminAccounts WHERE lower(trim(name))='rafael cunha' AND accountType IN ('both','admin') ORDER BY id LIMIT 1) FROM adminAccounts a WHERE accountType IN ('agent','both') AND lower(trim(name))<>'rafael cunha' AND EXISTS(SELECT 1 FROM adminAccounts WHERE lower(trim(name))='rafael cunha' AND accountType IN ('both','admin'));
INSERT OR IGNORE INTO portalWhatsappGrants(email,enabled,updatedBy) SELECT lower(email),1,'initial-rafael-authorization' FROM adminAccounts WHERE lower(trim(name))='rafael cunha' AND accountType IN ('both','admin') ORDER BY id LIMIT 1;
INSERT OR IGNORE INTO portalWhatsappGrants(email,enabled,updatedBy) SELECT lower(p.email),1,'initial-rafael-authorization' FROM portalAssistants p JOIN assistantAgentAccess l ON l.assistantId=p.id JOIN adminAccounts a ON lower(a.email)=lower(l.owner) WHERE lower(trim(p.name))='beatriz procknow' AND p.active=1 AND p.deletedAt IS NULL AND l.active=1 AND lower(trim(a.name))='rafael cunha';
